.btn-group {
  display: flex;

  flex-wrap: wrap;
}

.button {

  background-color: #04AA6D;
  border: none;
  color: white;

  padding: 15px 32px;
  text-align: center;
  text-decoration:
  none;
  font-size: 16px;
  cursor: pointer;
}

.btn-group .button:hover {
  background-color:
  dodgerblue;
}
